```java
// ─── File: src/main/java/com/bank/leak/model/SafeAccount.java ───
// (Recommended) TRUE ENCAPSULATION: private field + defensive return
package com.bank.leak.model;

import java.math.BigDecimal;
import java.util.ArrayList;
import java.util.Collections;
import java.util.List;
import java.util.stream.Stream;

public class SafeAccount {
    private final String accountId;
    private final List<Transaction> transactions = new ArrayList<>();

    public SafeAccount(String accountId) { this.accountId = accountId; }

    public void addTransaction(Transaction txn) {
        if (txn.amount().signum() <= 0) throw new IllegalArgumentException("Amount must be positive!");
        transactions.add(txn);
    }

    // (Recommended) FIX 1: unmodifiable view
    public List<Transaction> getTransactionsView() {
        return Collections.unmodifiableList(transactions);
        // add/remove/clear → UnsupportedOperationException!
    }

    // (Recommended) FIX 2: defensive copy
    public List<Transaction> getTransactionsCopy() {
        return new ArrayList<>(transactions);
        // Returns NEW list — caller can mutate the copy without affecting us
    }

    // (Recommended) FIX 3: List.copyOf (Java 10) — unmodifiable + copy
    public List<Transaction> getTransactions() {
        return List.copyOf(transactions);
        // Unmodifiable AND a separate copy — best of both worlds!
    }

    // (Recommended) FIX 4: Stream — read-only pipeline
    public Stream<Transaction> transactionStream() {
        return transactions.stream();
    }

    public int getTransactionCount() { return transactions.size(); }
    public String getAccountId() { return accountId; }
}
```

```java
// ─── File: src/test/java/com/bank/leak/EncapsulationLeakTest.java ───
package com.bank.leak;

import com.bank.leak.model.*;
import org.junit.jupiter.api.Test;
import java.math.BigDecimal;
import static org.assertj.core.api.Assertions.*;

class EncapsulationLeakTest {

    // ═══ BROKEN: private field mutated through getter ═══
    @Test
    void broken_callerCanAddWithoutValidation() {
        BrokenAccount account = new BrokenAccount("SAV001");
        account.addTransaction(new Transaction("TXN-001", new BigDecimal("5000"), "CREDIT"));

        // (Avoid) BYPASS validation: add negative-amount transaction via leaked getter!
        account.getTransactions().add(new Transaction("FAKE", new BigDecimal("-99999"), "HACK"));
        // addTransaction() would have thrown IllegalArgumentException! But we bypassed it.
        assertThat(account.getTransactions()).hasSize(2);  // FAKE transaction is IN the list!
    }

    @Test
    void broken_callerCanClearAllTransactions() {
        BrokenAccount account = new BrokenAccount("SAV001");
        account.addTransaction(new Transaction("TXN-001", new BigDecimal("5000"), "CREDIT"));
        account.addTransaction(new Transaction("TXN-002", new BigDecimal("3000"), "CREDIT"));

        // (Avoid) WIPE all transactions via leaked getter!
        account.getTransactions().clear();
        assertThat(account.getTransactions()).isEmpty();  // ALL GONE! No audit, no authorization!
    }

    // ═══ SAFE: unmodifiable view blocks mutation ═══
    @Test
    void safe_unmodifiableViewBlocksAdd() {
        SafeAccount account = new SafeAccount("SAV001");
        account.addTransaction(new Transaction("TXN-001", new BigDecimal("5000"), "CREDIT"));

        assertThatThrownBy(() ->
            account.getTransactionsView().add(new Transaction("FAKE", new BigDecimal("-99"), "HACK")))
            .isInstanceOf(UnsupportedOperationException.class);
        assertThat(account.getTransactionCount()).isEqualTo(1);  // internal list SAFE!
    }

    @Test
    void safe_unmodifiableViewBlocksClear() {
        SafeAccount account = new SafeAccount("SAV001");
        account.addTransaction(new Transaction("TXN-001", new BigDecimal("5000"), "CREDIT"));

        assertThatThrownBy(() -> account.getTransactionsView().clear())
            .isInstanceOf(UnsupportedOperationException.class);
        assertThat(account.getTransactionCount()).isEqualTo(1);  // NOT cleared!
    }

    // ═══ SAFE: defensive copy — caller modifies copy only ═══
    @Test
    void safe_defensiveCopyIsolatesInternalList() {
        SafeAccount account = new SafeAccount("SAV001");
        account.addTransaction(new Transaction("TXN-001", new BigDecimal("5000"), "CREDIT"));

        var copy = account.getTransactionsCopy();
        copy.add(new Transaction("FAKE", new BigDecimal("-99"), "HACK"));  // modifies COPY
        copy.clear();  // clears COPY

        assertThat(account.getTransactionCount()).isEqualTo(1);  // internal list UNAFFECTED!
    }

    // ═══ SAFE: List.copyOf — unmodifiable + copy ═══
    @Test
    void safe_listCopyOfBlocksAndIsolates() {
        SafeAccount account = new SafeAccount("SAV001");
        account.addTransaction(new Transaction("TXN-001", new BigDecimal("5000"), "CREDIT"));

        var safe = account.getTransactions();
        assertThatThrownBy(() -> safe.add(new Transaction("FAKE", BigDecimal.ONE, "X")))
            .isInstanceOf(UnsupportedOperationException.class);
        assertThat(account.getTransactionCount()).isEqualTo(1);
    }

    // ═══ IMMUTABLE RECORD: elements cannot be mutated ═══
    @Test
    void immutableRecord_elementsCannotBeMutated() {
        Transaction txn = new Transaction("TXN-001", new BigDecimal("5000"), "CREDIT");
        // txn.setAmount(BigDecimal.ZERO);  → COMPILE ERROR! Record has no setter!
        // Record fields are final — true immutability at the element level.
        assertThat(txn.amount()).isEqualByComparingTo("5000");
    }
}
```

